const answers = [
  { id: 1, question: "What is React?", correct: true },
  { id: 2, question: "Is HTML a programming language?", correct: false },
  { id: 3, question: "What is a component?", correct: true }
];

export const readingRepo = {
  getAnswers: () => answers
};
